choose.otherwise:
SELECT AAA.* 
FROM (
	SELECT ROW_NUMBER() OVER(ORDER BY created_at DESC) as r, users.* 
	FROM users
) AAA 
WHERE AAA.r BETWEEN #{begin} AND #{end}

